// Shipwright-authored plank join. Reports the seam-to-plank-to-step-pattern join for this
// project and reddens where the join fails. Also runs the verification-conformance rule set
// listed under `scantlings` in RIGGING.md, which is the conformance part this method carries.
//
// Annotation reading is text based: this stack ships no docblock reader for plain JavaScript,
// so the reader recognizes a docblock by its own delimiters and the declaration that follows.
// The weakness is recorded as a harbour finding in RIGGING.md's fit report.

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();

function readRigging() {
	const text = fs.readFileSync(path.join(ROOT, 'RIGGING.md'), 'utf8');
	const values = {};
	let section = '';
	for (const line of text.split('\n')) {
		const heading = line.match(/^##\s+(.+?)\s*$/);
		if (heading) {
			section = heading[1].toLowerCase();
			continue;
		}
		const item = line.match(/^-\s+([A-Za-z-]+):\s*(.+?)\s*$/);
		if (!item) continue;
		const key = `${section}.${item[1]}`;
		(values[key] ||= []).push(item[2].replace(/^`|`$/g, ''));
	}
	return values;
}

function walk(dir, out = []) {
	if (!fs.existsSync(dir)) return out;
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const full = path.join(dir, entry.name);
		if (entry.isDirectory()) walk(full, out);
		else out.push(full);
	}
	return out;
}

const SOURCE = /\.(js|mjs|cjs)$/;
const DECLARATION =
	/^\s*(?:export\s+)?(?:default\s+)?(?:async\s+)?(?:function\s*\*?\s*[A-Za-z_$][\w$]*|class\s+[A-Za-z_$][\w$]*|(?:const|let|var)\s+[A-Za-z_$][\w$]*\s*=|[A-Za-z_$][\w$]*\s*[:(])/;

// A named function definition is this project's seam unit.
const NAMED_FUNCTION = [
	/^\s*(?:export\s+)?(?:async\s+)?function\s*\*?\s*([A-Za-z_$][\w$]*)\s*\(/,
	/^\s*(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s+)?(?:function\b|\([^)]*\)\s*=>|[A-Za-z_$][\w$]*\s*=>)/,
];

function readPlanks(files) {
	const planks = [];
	for (const file of files) {
		const lines = fs.readFileSync(file, 'utf8').split('\n');
		let inBlock = false;
		let blockPlanks = [];
		let blockStart = 0;
		for (let i = 0; i < lines.length; i++) {
			const line = lines[i];
			if (!inBlock && /\/\*\*/.test(line)) {
				inBlock = true;
				blockPlanks = [];
				blockStart = i + 1;
			}
			if (inBlock) {
				for (const m of line.matchAll(/@planks(-provisional)?\(\s*(['"])(.*?)\2\s*\)/g)) {
					blockPlanks.push({ provisional: Boolean(m[1]), text: m[3], line: i + 1 });
				}
				if (/\*\//.test(line)) {
					inBlock = false;
					let next = i + 1;
					while (next < lines.length && lines[next].trim() === '') next++;
					const attached = next < lines.length && DECLARATION.test(lines[next]);
					for (const p of blockPlanks) planks.push({ ...p, file, attached, blockStart });
					blockPlanks = [];
				}
				continue;
			}
			for (const m of line.matchAll(/@planks(-provisional)?\(\s*(['"])(.*?)\2\s*\)/g)) {
				planks.push({
					provisional: Boolean(m[1]),
					text: m[3],
					line: i + 1,
					file,
					attached: false,
					blockStart: i + 1,
				});
			}
		}
	}
	return planks;
}

function readSeams(files) {
	const seams = [];
	for (const file of files) {
		const lines = fs.readFileSync(file, 'utf8').split('\n');
		for (let i = 0; i < lines.length; i++) {
			for (const pattern of NAMED_FUNCTION) {
				const m = lines[i].match(pattern);
				if (!m) continue;
				let above = i - 1;
				while (above >= 0 && lines[above].trim() === '') above--;
				let planked = false;
				if (above >= 0 && /\*\//.test(lines[above])) {
					for (let j = above; j >= 0; j--) {
						if (/@planks(-provisional)?\(/.test(lines[j])) planked = true;
						if (/\/\*\*/.test(lines[j])) break;
					}
				}
				seams.push({ file, line: i + 1, name: m[1], planked });
				break;
			}
		}
	}
	return seams;
}

const STEP_PATTERN =
	/\b(?:Given|When|Then)\s*\(\s*(?:(['"])((?:\\.|[^\\])*?)\1|\/((?:\\.|[^\\/])*?)\/[a-z]*)/g;

function readStepPatterns(files) {
	const patterns = new Map();
	for (const file of files) {
		const text = fs.readFileSync(file, 'utf8');
		for (const m of text.matchAll(STEP_PATTERN)) {
			const value = m[2] !== undefined ? m[2] : `/${m[3]}/`;
			(patterns.get(value) || patterns.set(value, []).get(value)).push(file);
		}
	}
	return patterns;
}

function readCaptainScenarios(specDirs) {
	const scenarios = new Set();
	for (const dir of specDirs) {
		for (const file of walk(dir).filter((f) => f.endsWith('.feature'))) {
			const lines = fs.readFileSync(file, 'utf8').split('\n');
			for (let i = 0; i < lines.length; i++) {
				if (!/@captain\b/.test(lines[i])) continue;
				for (let j = i + 1; j < lines.length; j++) {
					const name = lines[j].match(/^\s*Scenario(?: Outline)?:\s*(.+?)\s*$/);
					if (name) {
						scenarios.add(`${path.relative(ROOT, file)}:${name[1]}`);
						break;
					}
					if (lines[j].trim() !== '' && !/^\s*@/.test(lines[j])) break;
				}
			}
		}
	}
	return scenarios;
}

function runConformanceRules(rulesPath, verificationFiles, joinFacts) {
	const failures = [];
	if (!rulesPath || rulesPath === 'none' || !fs.existsSync(rulesPath)) return failures;
	const ruleSet = JSON.parse(fs.readFileSync(rulesPath, 'utf8'));
	for (const rule of ruleSet.rules) {
		if (rule.kind === 'plank-form') {
			for (const p of joinFacts.malformed)
				failures.push(`${rule.id}: ${p.file}:${p.line} plank "${p.text}" ${p.reason}`);
			continue;
		}
		if (rule.kind === 'plank-coverage') {
			for (const s of joinFacts.unplanked)
				failures.push(`${rule.id}: ${s.file}:${s.line} seam "${s.name}" carries no plank`);
			continue;
		}
		if (rule.kind !== 'text-pattern') continue;
		const forbid = new RegExp(rule.pattern, 'g');
		const allow = rule.allowNear ? new RegExp(rule.allowNear) : null;
		for (const file of verificationFiles) {
			const lines = fs.readFileSync(file, 'utf8').split('\n');
			for (let i = 0; i < lines.length; i++) {
				if (!forbid.test(lines[i])) continue;
				forbid.lastIndex = 0;
				const window = lines.slice(Math.max(0, i - 3), i + 4).join('\n');
				if (allow && allow.test(window)) continue;
				failures.push(`${rule.id}: ${file}:${i + 1} ${rule.message}`);
			}
		}
	}
	return failures;
}

const rigging = readRigging();
const implementationDirs = rigging['directories.implementation'] || [];
const specDirs = rigging['directories.specs'] || [];
const verificationDirs = rigging['directories.verification'] || [];
const scantlings = rigging['directories.scantlings'] || [];

const implementationFiles = implementationDirs.flatMap((d) => walk(d)).filter((f) => SOURCE.test(f));
const verificationFiles = verificationDirs.flatMap((d) => walk(d)).filter((f) => SOURCE.test(f));

const planks = readPlanks(implementationFiles);
const seams = readSeams(implementationFiles);
const patterns = readStepPatterns(verificationFiles);
const captainScenarios = readCaptainScenarios(specDirs);

const malformed = [];
for (const p of planks) {
	if (!p.attached) {
		malformed.push({ ...p, reason: 'is not a docblock tag on a declaration' });
		continue;
	}
	if (p.provisional) {
		if (!captainScenarios.has(p.text))
			malformed.push({ ...p, reason: 'names no scenario that still carries @captain' });
		continue;
	}
	if (!patterns.has(p.text))
		malformed.push({ ...p, reason: 'matches no current step-definition pattern' });
}
const unplanked = seams.filter((s) => !s.planked);

console.log('# plank join');
console.log(`implementation files: ${implementationFiles.length}`);
console.log(`step-definition patterns: ${patterns.size}`);
console.log(`seams: ${seams.length}, planked: ${seams.length - unplanked.length}`);
for (const [pattern, files] of patterns) {
	const bound = planks.filter((p) => !p.provisional && p.text === pattern);
	const where = bound.map((p) => `${p.file}:${p.line}`).join(', ') || 'no plank';
	console.log(`  "${pattern}" <- ${where} (defined in ${files.map((f) => f).join(', ')})`);
}
for (const p of planks.filter((p) => p.provisional))
	console.log(`  provisional ${p.file}:${p.line} -> ${p.text}`);

const conformanceFailures = runConformanceRules(scantlings.find((s) => /conformance/.test(s)), verificationFiles, {
	malformed,
	unplanked,
});

console.log('# conformance');
console.log(conformanceFailures.length === 0 ? 'no rule breaches' : conformanceFailures.join('\n'));

const errors = [
	...malformed.map((p) => `plank ${p.file}:${p.line} "${p.text}" ${p.reason}`),
	...unplanked.map((s) => `seam ${s.file}:${s.line} "${s.name}" carries no plank`),
	...conformanceFailures,
];

if (errors.length > 0) {
	console.error('# join failed');
	for (const e of errors) console.error(e);
	process.exit(1);
}
console.log('# join clean');

{
  "name": "verification-conformance",
  "description": "Static rules over this project's verification support and plank annotations. The plank-join method discharges them. A new debt kind lands here as a rule entry, never as a new scenario.",
  "rules": [
    {
      "id": "plank-form",
      "kind": "plank-form",
      "message": "every @planks and @planks-provisional token is a docblock tag on a declaration, every @planks string is a current step-definition pattern, and every @planks-provisional reference names a scenario that still carries @captain"
    },
    {
      "id": "plank-coverage",
      "kind": "plank-coverage",
      "message": "every named production seam carries at least one plank"
    },
    {
      "id": "no-guessed-delay",
      "kind": "text-pattern",
      "pattern": "setTimeout\\s*\\(|new Promise\\s*\\(\\s*\\(?\\s*resolve\\s*\\)?\\s*=>\\s*setTimeout",
      "message": "guessed delay in verification support; end the wait on an observed signal",
      "allowNear": "@exceptional-double"
    },
    {
      "id": "no-forbidden-doubles",
      "kind": "text-pattern",
      "pattern": "\\b(sinon|jest\\.mock|createMock|makeFake|stubbed|FakeStorage|MockWindow)\\b",
      "message": "test double in verification support; exercise the real artifact or mark the double @exceptional-double with its condition",
      "allowNear": "@exceptional-double"
    },
    {
      "id": "no-handbuilt-dom",
      "kind": "text-pattern",
      "pattern": "innerHTML\\s*=\\s*[`'\"]\\s*<",
      "message": "hand-built DOM in verification support; drive the real page the world loads",
      "allowNear": "@exceptional-double"
    }
  ]
}

